def _delta_to_alpha(self, delta: float) -> float:
    """Convert discretization error to purity alpha."""
    if delta < 1e-15:
        return self.config.ALPHA_SATURATION
    return -np.log(delta + 1e-15)

def _delta_to_alpha(self, delta: float) -> float:
    if delta < 1e-15:
