                    'val_acc': data.get('val_acc', metrics.get('val_acc', 0.0)),
                    'alpha': metrics.get('alpha', 0.0),
                    'epoch': data.get('epoch', 0)
                }
        except Exception:
            pass

        return {
            'mse': 1.0,
            'val_acc': 0.0,
            'alpha': 0.0,
            'epoch': 0
        }


