        MATRIX_SIZE=args.matrix_size,
        INPUT_DIM=args.matrix_size ** 2,
        OUTPUT_DIM=args.matrix_size ** 2,
        OUTPUT_DIRECTORY=args.output or CONFIG.OUTPUT_DIRECTORY
    )

def get_coefficients(self) -> Dict[str, torch.Tensor]:
    return {
