def benchmark(func, A, B, warmup=2, runs=5):
    """Run benchmark with warmup"""
    # Warmup
    for _ in range(warmup):
        _ = func(A, B)

    # Timed runs
    times = []
    for _ in range(runs):
        start = time.perf_counter()
        C = func(A, B)
        end = time.perf_counter()
        times.append(end - start)

    return np.min(times), np.mean(times), np.max(times), C

