def __init__(self, tolerance: float = 1e-4, verbose: bool = True):
    self.tol = tolerance
    self.verbose = verbose

def _detect_block_structure(self, W: torch.Tensor) -> Tuple[int, int]:
    """Detect repeating block patterns"""
    m, n = W.shape

    # Try common block sizes
    best_block = (m, n)
    best_score = float('inf')

    for bm in range(1, m + 1):
        if m % bm != 0:
            continue
        for bn in range(1, n + 1):
            if n % bn != 0:
                continue

            score = self._block_repetition_score(W, bm, bn)
            if score < best_score:
                best_score = score
                best_block = (bm, bn)

    return best_block

def _block_repetition_score(self, W: torch.Tensor, bm: int, bn: int) -> float:
    """Score how well blocks repeat (lower = more repetitive)"""
    m, n = W.shape
    blocks = []

    for i in range(0, m, bm):
        for j in range(0, n, bn):
            blocks.append(W[i:i+bm, j:j+bn].flatten())

    if len(blocks) <= 1:
        return float('inf')

    # Compute variance across blocks
    stacked = torch.stack(blocks)
    variance = stacked.var(dim=0).mean().item()
    return variance

def _detect_symmetry_type(self, W: torch.Tensor) -> str:
    """Detect type of symmetry in weight matrix"""
    m, n = W.shape

    # Check for permutation symmetry (rows are permutations of each other)
    if self._is_permutation_symmetric(W):
        return 'permutation'

    # Check for reflection symmetry
    if m == n:
        if torch.allclose(W, W.T, atol=self.tol):
            return 'symmetric'
        if torch.allclose(W, -W.T, atol=self.tol):
            return 'antisymmetric'

    # Check for cyclic structure
    if self._is_cyclic(W):
        return 'cyclic'

    return 'none'

def _is_permutation_symmetric(self, W: torch.Tensor) -> bool:
    """Check if rows are permutations of a base pattern"""
    sorted_rows = torch.sort(W, dim=1)[0]
    return torch.allclose(sorted_rows[0:1].expand_as(sorted_rows), 
                        sorted_rows, atol=self.tol)

def _is_cyclic(self, W: torch.Tensor) -> bool:
    """Check for cyclic/Toeplitz structure"""
    m, n = W.shape
    if m < 2:
        return False

    # Check if each row is a shift of the previous
    for i in range(1, min(m, 3)):
        shifted = torch.roll(W[0], i)
        if not torch.allclose(W[i], shifted, atol=self.tol):
            return False
    return True

def _validate_expansion(self, expanded: Dict, structure: SymmetryStructure):
    """Validate that expansion preserves key invariants"""
    if self.verbose:
        print("\n--- Expansion Validation ---")
        print(f"Rank preserved: {structure.rank}")
        print(f"Discrete values preserved: {structure.discretization_values}")
        print(f"Confidence: {structure.confidence:.3f}")

        if structure.confidence > 0.9:
            print("[OK] High confidence expansion")
        elif structure.confidence > 0.5:
            print("[WARN] Medium confidence - verify numerically")
        else:
            print("[FAIL] Low confidence - expansion may fail")

static float* alloc_matrix(int n) {
    return (float*)aligned_alloc(32, n * n * sizeof(float));
}

/* Standard matrix multiplication for small matrices */

static void matmul_standard(float* C, float* A, float* B, int n) {
    memset(C, 0, n * n * sizeof(float));
    for (int i = 0; i < n; i++) {
        for (int k = 0; k < n; k++) {
            float a_ik = A[i * n + k];
            for (int j = 0; j < n; j++) {
                C[i * n + j] += a_ik * B[k * n + j];
            }
        }
    }
}

/* Add matrices: C = A + B */

static void mat_add(float* C, float* A, float* B, int n) {
    int nn = n * n;
    for (int i = 0; i < nn; i++) {
        C[i] = A[i] + B[i];
    }
}

/* Subtract matrices: C = A - B */

static void mat_sub(float* C, float* A, float* B, int n) {
    int nn = n * n;
    for (int i = 0; i < nn; i++) {
        C[i] = A[i] - B[i];
    }
}

/* Extract quadrant from matrix */

static void extract_quadrant(float* Q, float* M, int n, int row, int col) {
    int h = n / 2;
    for (int i = 0; i < h; i++) {
        memcpy(&Q[i * h], &M[(row + i) * n + col], h * sizeof(float));
    }
}

/* Insert quadrant into matrix */

static void insert_quadrant(float* M, float* Q, int n, int row, int col) {
    int h = n / 2;
    for (int i = 0; i < h; i++) {
        memcpy(&M[(row + i) * n + col], &Q[i * h], h * sizeof(float));
    }
}

/* Strassen recursive */

void strassen_recursive(float* C, float* A, float* B, int n) {
    if (n <= THRESHOLD) {
        matmul_standard(C, A, B, n);
        return;
    }

    int h = n / 2;
    int hh = h * h;

    /* Allocate submatrices */
    float *A11 = alloc_matrix(h), *A12 = alloc_matrix(h);
    float *A21 = alloc_matrix(h), *A22 = alloc_matrix(h);
    float *B11 = alloc_matrix(h), *B12 = alloc_matrix(h);
    float *B21 = alloc_matrix(h), *B22 = alloc_matrix(h);

    float *M1 = alloc_matrix(h), *M2 = alloc_matrix(h);
    float *M3 = alloc_matrix(h), *M4 = alloc_matrix(h);
    float *M5 = alloc_matrix(h), *M6 = alloc_matrix(h);
    float *M7 = alloc_matrix(h);

    float *T1 = alloc_matrix(h), *T2 = alloc_matrix(h);

    /* Extract quadrants */
    extract_quadrant(A11, A, n, 0, 0);
    extract_quadrant(A12, A, n, 0, h);
    extract_quadrant(A21, A, n, h, 0);
    extract_quadrant(A22, A, n, h, h);

    extract_quadrant(B11, B, n, 0, 0);
    extract_quadrant(B12, B, n, 0, h);
    extract_quadrant(B21, B, n, h, 0);
    extract_quadrant(B22, B, n, h, h);

    /* M1 = (A11 + A22)(B11 + B22) */
    mat_add(T1, A11, A22, h);
    mat_add(T2, B11, B22, h);
    strassen_recursive(M1, T1, T2, h);

    /* M2 = (A21 + A22) * B11 */
    mat_add(T1, A21, A22, h);

void strassen_multiply(float* C, float* A, float* B, int n) {
    strassen_recursive(C, A, B, n);
}

/* Standard multiply for comparison */

void standard_multiply(float* C, float* A, float* B, int n) {
    matmul_standard(C, A, B, n);
}

static void strassen_level(float* C, float* A, float* B, int n, 
                           float* workspace, int ws_offset) {
    if (n < STRASSEN_THRESHOLD) {
        cblas_sgemm(CblasRowMajor, CblasNoTrans, CblasNoTrans,
                    n, n, n, 1.0f, A, n, B, n, 0.0f, C, n);
        return;
    }

    int h = n / 2;
    int hh = h * h;

    /* Use pre-allocated workspace */
    float* T1 = workspace + ws_offset;
    float* T2 = T1 + hh;
    float* M = T2 + hh;
    int next_offset = ws_offset + 3 * hh;

    /* Pointers to quadrants (no copy needed for input) */
    float* A11 = A;
    float* A12 = A + h;
    float* A21 = A + h * n;
    float* A22 = A + h * n + h;

    float* B11 = B;
    float* B12 = B + h;
    float* B21 = B + h * n;
    float* B22 = B + h * n + h;

    float* C11 = C;
    float* C12 = C + h;
    float* C21 = C + h * n;
    float* C22 = C + h * n + h;

    /* We need to extract quadrants for recursive calls */
    /* This is the overhead that makes Strassen slower for small n */
    float* qA11 = workspace + next_offset; next_offset += hh;
    float* qA12 = workspace + next_offset; next_offset += hh;
    float* qA21 = workspace + next_offset; next_offset += hh;
    float* qA22 = workspace + next_offset; next_offset += hh;
    float* qB11 = workspace + next_offset; next_offset += hh;

void strassen_optimal(float* C, float* A, float* B, int n) {
    if (n < STRASSEN_THRESHOLD) {
        /* Just use BLAS directly for small matrices */
        cblas_sgemm(CblasRowMajor, CblasNoTrans, CblasNoTrans,
                    n, n, n, 1.0f, A, n, B, n, 0.0f, C, n);
        return;
    }

    /* Allocate workspace (enough for all levels) */
    size_t ws_size = 20 * n * n * sizeof(float);
    float* workspace = (float*)aligned_alloc(64, ws_size);

    strassen_level(C, A, B, n, workspace, 0);

    free(workspace);
}

static inline float* alloc_matrix(int n) {
    return (float*)aligned_alloc(ALIGN, n * n * sizeof(float));
}

/* AVX2 vectorized matrix addition: C = A + B */

static void mat_add_avx(float* __restrict C, const float* __restrict A, 
                        const float* __restrict B, int n) {
    int nn = n * n;
    int i = 0;

    /* Process 8 floats at a time with AVX */
    for (; i <= nn - 8; i += 8) {
        __m256 va = _mm256_load_ps(&A[i]);
        __m256 vb = _mm256_load_ps(&B[i]);
        __m256 vc = _mm256_add_ps(va, vb);
        _mm256_store_ps(&C[i], vc);
    }

    /* Handle remainder */
    for (; i < nn; i++) {
        C[i] = A[i] + B[i];
    }
}

/* AVX2 vectorized matrix subtraction: C = A - B */

static void mat_sub_avx(float* __restrict C, const float* __restrict A, 
                        const float* __restrict B, int n) {
    int nn = n * n;
    int i = 0;

    for (; i <= nn - 8; i += 8) {
        __m256 va = _mm256_load_ps(&A[i]);
        __m256 vb = _mm256_load_ps(&B[i]);
        __m256 vc = _mm256_sub_ps(va, vb);
        _mm256_store_ps(&C[i], vc);
    }

    for (; i < nn; i++) {
        C[i] = A[i] - B[i];
    }
}

/* Cache-blocked matrix multiplication with AVX2 */

static void matmul_blocked_avx(float* __restrict C, const float* __restrict A, 
                               const float* __restrict B, int n) {
    memset(C, 0, n * n * sizeof(float));

    #pragma omp parallel for collapse(2) schedule(static)
    for (int ii = 0; ii < n; ii += BLOCK_SIZE) {
        for (int jj = 0; jj < n; jj += BLOCK_SIZE) {
            for (int kk = 0; kk < n; kk += BLOCK_SIZE) {
                int i_end = (ii + BLOCK_SIZE < n) ? ii + BLOCK_SIZE : n;
                int j_end = (jj + BLOCK_SIZE < n) ? jj + BLOCK_SIZE : n;
                int k_end = (kk + BLOCK_SIZE < n) ? kk + BLOCK_SIZE : n;

                for (int i = ii; i < i_end; i++) {
                    for (int k = kk; k < k_end; k++) {
                        float a_ik = A[i * n + k];
                        __m256 va = _mm256_set1_ps(a_ik);

                        int j = jj;
                        for (; j <= j_end - 8; j += 8) {
                            __m256 vb = _mm256_loadu_ps(&B[k * n + j]);
                            __m256 vc = _mm256_loadu_ps(&C[i * n + j]);
                            vc = _mm256_fmadd_ps(va, vb, vc);
                            _mm256_storeu_ps(&C[i * n + j], vc);
                        }

                        for (; j < j_end; j++) {
                            C[i * n + j] += a_ik * B[k * n + j];
                        }
                    }
                }
            }
        }
    }
}

/* Extract quadrant */

static void extract_quadrant(float* __restrict Q, const float* __restrict M, 
                            int n, int row, int col) {
    int h = n / 2;
    #pragma omp parallel for if(h > 64)
    for (int i = 0; i < h; i++) {
        memcpy(&Q[i * h], &M[(row + i) * n + col], h * sizeof(float));
    }
}

/* Insert quadrant */

static void insert_quadrant(float* __restrict M, const float* __restrict Q, 
                           int n, int row, int col) {
    int h = n / 2;
    #pragma omp parallel for if(h > 64)
    for (int i = 0; i < h; i++) {
        memcpy(&M[(row + i) * n + col], &Q[i * h], h * sizeof(float));
    }
}

/* Strassen recursive with parallelism */

void strassen_turbo_recursive(float* C, float* A, float* B, int n, int depth) {
    if (n <= THRESHOLD) {
        matmul_blocked_avx(C, A, B, n);
        return;
    }

    int h = n / 2;

    /* Allocate all matrices */
    float *A11 = alloc_matrix(h), *A12 = alloc_matrix(h);
    float *A21 = alloc_matrix(h), *A22 = alloc_matrix(h);
    float *B11 = alloc_matrix(h), *B12 = alloc_matrix(h);
    float *B21 = alloc_matrix(h), *B22 = alloc_matrix(h);

    float *M1 = alloc_matrix(h), *M2 = alloc_matrix(h);
    float *M3 = alloc_matrix(h), *M4 = alloc_matrix(h);
    float *M5 = alloc_matrix(h), *M6 = alloc_matrix(h);
    float *M7 = alloc_matrix(h);

    float *T1 = alloc_matrix(h), *T2 = alloc_matrix(h);
    float *C11 = alloc_matrix(h), *C12 = alloc_matrix(h);
    float *C21 = alloc_matrix(h), *C22 = alloc_matrix(h);

    /* Extract quadrants */
    extract_quadrant(A11, A, n, 0, 0);
    extract_quadrant(A12, A, n, 0, h);
    extract_quadrant(A21, A, n, h, 0);
    extract_quadrant(A22, A, n, h, h);

    extract_quadrant(B11, B, n, 0, 0);
    extract_quadrant(B12, B, n, 0, h);
    extract_quadrant(B21, B, n, h, 0);
    extract_quadrant(B22, B, n, h, h);

    /* Compute 7 products - parallelize at top level */
    if (depth == 0 && n >= 512) {
        float *T1_1 = alloc_matrix(h), *T2_1 = alloc_matrix(h);
        float *T1_2 = alloc_matrix(h), *T2_2 = alloc_matrix(h);
        float *T1_3 = alloc_matrix(h);
        float *T1_4 = alloc_matrix(h);

void strassen_turbo(float* C, float* A, float* B, int n) {
    omp_set_num_threads(omp_get_max_threads());
    strassen_turbo_recursive(C, A, B, n, 0);
}

/* Get number of threads */

int get_num_threads(void) {
    return omp_get_max_threads();
}

